//! 🫨️ Complete seismic neutral subjects, independent SQLite and declaration-owned I/O laws.
use super::En1998Snapshot;
#[test]
fn sqlite_snapshot_en1998_owned_native_decoder_controls_physical_and_typed_construction(){
 use store::io::IoPayload;
 let controls:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🎛️control.json")).unwrap();
 let limits=SqliteDatabaseLimits::default();let mut snapshot=fixture();
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let payload=match encoding{SnapshotEncoding::Binary=>IoPayload::Binary(store::ArtifactPack::encode_pack(&snapshot)),SnapshotEncoding::Text=>IoPayload::Text(store::ArtifactDsl::print_dsl(&snapshot))};
  let restored=En1998Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(restored,snapshot);
  assert!(En1998Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|false,limits)).is_err());
  assert!(En1998Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:1,..limits})).is_err());
  assert!(En1998Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:1,..limits})).is_err());
 }
 snapshot.buildings[0].storeys[0].variables=vec![snapshot.buildings[0].storeys[0].variables[0].clone();controls["entityCount"].as_u64().unwrap()as usize];snapshot.annex="世界".repeat(controls["largeTextBytes"].as_u64().unwrap()as usize);
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let payload=match encoding{SnapshotEncoding::Binary=>IoPayload::Binary(store::ArtifactPack::encode_pack(&snapshot)),SnapshotEncoding::Text=>IoPayload::Text(store::ArtifactDsl::print_dsl(&snapshot))};let mut interior=false;let threshold=controls["cancelAt"].as_u64().unwrap()as usize;
  let mut callback=|event:store::sqlite_snapshot::SqliteSnapshotProgress|{if event.phase==SqliteSnapshotPhase::DecodeNative&&event.completed>=threshold&&event.completed<event.total{interior=true;false}else{true}};
  assert!(En1998Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut callback,limits)).is_err());assert!(interior,"{encoding:?}: canceled inside actual native work");
 }
}
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{export_sqlite_database,import_sqlite_database,SnapshotEncoding,SqliteDatabase,SqliteDatabaseLimits,SqliteSnapshotControl,SqliteSnapshotPhase,SqliteValue}};
fn fixture()->En1998Snapshot{semio_framework_pack_json::from_json_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json"), semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap()}
fn database(snapshot:&En1998Snapshot)->SqliteDatabase{snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn roundtrip(snapshot:&En1998Snapshot)->En1998Snapshot{let bytes=export_sqlite_database(&database(snapshot),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();En1998Snapshot::from_sqlite_database(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn set_every_word(s:&mut En1998Snapshot,v:f64){
 s.site.a_gr=v;
 for b in &mut s.buildings{b.plan_width_m=v;b.plan_length_m=v;b.t1_given_s=v;b.ct=v;b.nu=v;b.masonry_wall_area_ratio=v;b.accidental_eccentricity_ratio=v;for x in &mut b.systems{x.q0=v;x.alpha_u_over_alpha_1=v;x.k_w=v;x.base_shear_resistance_n=v;}for x in &mut b.storeys{x.height_m=v;x.permanent_gk_n=v;x.stiffness_x=v;x.stiffness_y=v;x.centre_of_mass_x_m=v;x.centre_of_mass_y_m=v;x.centre_of_stiffness_x_m=v;x.centre_of_stiffness_y_m=v;x.drift_x_m=v;x.drift_y_m=v;x.shear_resistance_n=v;for a in &mut x.variables{a.qk_n=v;}}for x in &mut b.members{x.min_dimension_m=v;x.rho=v;x.rho_prime=v;x.omega_wd=v;}}
 for x in &mut s.bridges{x.period_ratio=v;x.fundamental_period_s=v;x.v_rd_n=v;x.bearing_d_rd_m=v;x.permanent_gk_n=v;for a in &mut x.variables{a.qk_n=v;}}
 for x in &mut s.assessments{x.r_k_n=v;x.gamma_el=v;}
 for x in &mut s.silos{x.height_m=v;x.radius_m=v;x.permanent_gk_n=v;x.content_qk_n=v;x.filling_ratio=v;x.n_rd_n=v;x.v_rd_n=v;x.q_nominal=v;}
 for x in &mut s.tanks{x.height_m=v;x.radius_m=v;x.permanent_gk_n=v;x.content_qk_n=v;x.filling_ratio=v;x.v_rd_n=v;}
 for x in &mut s.foundations{x.area_m2=v;x.p_rd_pa=v;x.h_rd_n=v;x.k_foundation=v;x.k_soil=v;}
 for x in &mut s.retaining_walls{x.height_m=v;x.phi_deg=v;x.soil_gamma=v;x.r=v;x.h_rd_n_per_m=v;}
 for x in &mut s.towers{x.height_m=v;x.m_rd_nm=v;x.q_nominal=v;x.permanent_gk_n=v;for a in &mut x.variables{a.qk_n=v;}}
}
