#[test]
fn sqlite_snapshot_en1998_independent_sqlite_queries_all_components_and_applies_semantic_edits(){
 use std::{io::Write,process::{Command,Stdio}};
 let mut expected=fixture();let bytes=export_sqlite_database(&database(&expected),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();
 let script="import{Database}from'bun:sqlite';import{Buffer}from'node:buffer';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const b=db.query('SELECT b.ordinal,s.ordinal AS storey,v.ordinal AS variable,m.steel_section_class FROM en1998_building b JOIN en1998_system y ON y.building_id=b.id JOIN en1998_storey s ON s.building_id=b.id JOIN en1998_storey_variable v ON v.storey_id=s.id JOIN en1998_member m ON m.building_id=b.id').all();if(b.length!==1||b[0].ordinal!==0||b[0].variable!==0||b[0].steel_section_class!==255)throw Error('building ownership');for(const p of['bridge','tower'])if(db.query('SELECT v.id FROM en1998_'+p+' p JOIN en1998_'+p+'_variable v ON v.'+p+'_id=p.id').all().length!==1)throw Error('variable ownership');for(const p of['assessment','silo','tank','foundation','retaining_wall'])if(db.query('SELECT ordinal FROM en1998_'+p).get().ordinal!==0)throw Error('subject ownership');const w=Buffer.alloc(8);w.writeDoubleBE(0.625);db.run(\"UPDATE en1998_site SET a_gr=0.625,a_gr_ieee754_bits=?,a_gr_ieee754_class='finite',seismic_zone='zone1',de_ground_combo='A-R'\",[BigInt.asIntN(64,w.readBigUInt64BE())]);db.run(\"UPDATE en1998_document SET annex='Geändert 世界'\");w.writeDoubleBE(-0.25);db.run(\"UPDATE en1998_storey_variable SET qk_n=-0.25,qk_n_ieee754_bits=?,qk_n_ieee754_class='finite'\",[BigInt.asIntN(64,w.readBigUInt64BE())]);db.run('UPDATE en1998_member SET steel_section_class=0,detailing_compatible_with_q=1');db.run(\"UPDATE en1998_foundation SET building_logical_id='another unresolved'\");await Bun.write(Bun.stdout,db.serialize());db.close();";
 let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));expected.site.a_gr=0.625;expected.site.seismic_zone=crate::DeSeismicZone::Zone1;expected.site.de_ground_combo=crate::DeGroundCombo::AR;expected.annex="Geändert 世界".into();expected.buildings[0].storeys[0].variables[0].qk_n=-0.25;expected.buildings[0].members[0].steel_section_class=0;expected.buildings[0].members[0].detailing_compatible_with_q=true;expected.foundations[0].supported_building_id="another unresolved".into();assert_eq!(En1998Snapshot::from_sqlite_database(&import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),expected);
}
#[test]
fn sqlite_snapshot_en1998_refuses_malformed_choices_widths_booleans_parent_ordinals_words_and_mandatory_site(){
 let database=database(&fixture());for(table,column,value)in[("en1998_site",2,SqliteValue::Text("unknown".into())),("en1998_site",4,SqliteValue::Text("unknown".into())),("en1998_site",1,SqliteValue::Integer(99)),("en1998_member",11,SqliteValue::Integer(256)),("en1998_member",11,SqliteValue::Integer(-1)),("en1998_member",6,SqliteValue::Integer(2)),("en1998_building",7,SqliteValue::Integer(-1)),("en1998_storey",6,SqliteValue::Integer(2)),("en1998_bridge",9,SqliteValue::Integer(-1)),("en1998_tower",6,SqliteValue::Integer(2)),("en1998_site",9,SqliteValue::Text("nan".into()))]{let mut invalid=database.clone();invalid.table_mut(table).unwrap().rows[0].values[column]=value;assert!(En1998Snapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err(),"{table}");}
 for table in["en1998_building","en1998_system","en1998_storey","en1998_storey_variable","en1998_member","en1998_bridge","en1998_bridge_variable","en1998_assessment","en1998_silo","en1998_tank","en1998_foundation","en1998_retaining_wall","en1998_tower","en1998_tower_variable"]{for column in[1,2]{let mut invalid=database.clone();invalid.table_mut(table).unwrap().rows[0].values[column]=SqliteValue::Integer(99);assert!(En1998Snapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err(),"{table}");}let mut invalid=database.clone();let mut row=invalid.table(table).unwrap().rows[0].clone();row.rowid=2;row.values[0]=SqliteValue::Integer(2);invalid.table_mut(table).unwrap().rows.push(row);assert!(En1998Snapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err(),"duplicate ordinal {table}");}
 for table in["en1998_document","en1998_site"]{let mut invalid=database.clone();invalid.table_mut(table).unwrap().rows.clear();assert!(En1998Snapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err(),"{table}");}
}
#[test]
fn sqlite_snapshot_en1998_initial_and_nested_operations_support_cancellation_and_borrowed_native_admission(){
 let mut snapshot=fixture();assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:1,..SqliteDatabaseLimits::default()})).is_err());assert!(En1998Snapshot::from_sqlite_database(&database(&snapshot),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:0,..SqliteDatabaseLimits::default()})).is_err());
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:1024,..SqliteDatabaseLimits::default()})).unwrap_err().to_string().contains("native encoding exceeds file byte limit"));}
 let controls:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🎛️control.json")).unwrap();snapshot.buildings[0].storeys[0].variables=vec![snapshot.buildings[0].storeys[0].variables[0].clone();controls["entityCount"].as_u64().unwrap()as usize];let cancel_at=controls["cancelAt"].as_u64().unwrap()as usize;
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let mut reached=false;assert!(snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut|event|{if event.phase==SqliteSnapshotPhase::EncodeNative&&event.completed>=cancel_at{reached=true;false}else{true}},SqliteDatabaseLimits::default())).is_err());assert!(reached);}
 let large=database(&snapshot);for phase in[SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::ReconstructSnapshot]{let mut reached=false;let mut callback=|event:store::sqlite_snapshot::SqliteSnapshotProgress|{if event.phase==phase&&event.completed>=cancel_at{reached=true;false}else{true}};let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());assert!(if phase==SqliteSnapshotPhase::ProjectSnapshot{snapshot.to_sqlite_database(&mut control).is_err()}else{En1998Snapshot::from_sqlite_database(&large,&mut control).is_err()});assert!(reached);}
}
#[test]
fn sqlite_snapshot_en1998_large_owned_text_cancels_before_projection_reconstruction_and_native_encoding_copy(){let mut snapshot=fixture();snapshot.annex="x".repeat(131073);let database=database(&snapshot);for phase in[SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::ReconstructSnapshot,SqliteSnapshotPhase::EncodeNative]{let mut reached=false;let mut callback=|event:store::sqlite_snapshot::SqliteSnapshotProgress|{if event.phase==phase&&event.total>=65536&&event.completed>=65536&&event.completed<event.total{reached=true;false}else{true}};let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());let rejected=match phase{SqliteSnapshotPhase::ProjectSnapshot=>snapshot.to_sqlite_database(&mut control).is_err(),SqliteSnapshotPhase::ReconstructSnapshot=>En1998Snapshot::from_sqlite_database(&database,&mut control).is_err(),_=>snapshot.encode_sqlite_snapshot_native(SnapshotEncoding::Text,&mut control).is_err()};assert!(rejected);assert!(reached);}}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_en1998_actual_erased_codec_and_declaration_preserve_every_owned_word(){
 use store::io::{ArtifactDialect,IoPayload,io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot}};
 semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("norm").label("EN1998 owned SQLite").version("0.0.1").package_id("semio:norm").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();let codec=store::document_codec(crate::EN1998_DOCUMENT_SCHEMA).await.unwrap().unwrap();let provider=codec.snapshot_sqlite.as_ref().unwrap();let dialect=ArtifactDialect{artifact_kind:"s.norm.en1998".into(),standard:"1".into(),subset:"*".into()};
 let words:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔢️binary64.json")).unwrap();for word in words["ieee754Binary64Bits"].as_array().unwrap(){let mut snapshot=fixture();set_every_word(&mut snapshot,f64::from_bits(word.as_str().unwrap().parse().unwrap()));let expected=database(&snapshot);for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>IoPayload::Binary(<En1998Snapshot as store::ArtifactPack>::encode_pack_with(&snapshot,&store::PackEncodeOptions::default()).unwrap()),SnapshotEncoding::Text=>IoPayload::Text(<En1998Snapshot as store::ArtifactDsl>::print_dsl(&snapshot))};let result=(provider.export)(&codec.schema,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(result,expected);let result=(provider.import)(&codec.schema,&dialect,result,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let restored=match result{IoPayload::Binary(bytes)=><En1998Snapshot as store::ArtifactPack>::decode_pack(&bytes).unwrap(),IoPayload::Text(text)=><En1998Snapshot as store::ArtifactDsl>::parse_dsl(&text).unwrap()};assert_eq!(database(&restored),expected);}}
 let snapshot=fixture();let output=io_export_sqlite_snapshot(&dialect,&snapshot,SnapshotEncoding::Binary,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap();assert_eq!(io_import_sqlite_snapshot::<En1998Snapshot>(&dialect,&output.value,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value,snapshot);
}

#[test]
fn sqlite_snapshot_en1998_genuine_output_admits_exact_row_and_file_frontiers(){
 use store::{ArtifactSqliteSnapshot as _,sqlite_snapshot::{SqliteDatabaseLimits,SqliteSnapshotControl,SnapshotEncoding,export_sqlite_database}};
 use std::{io::Write,process::{Command,Stdio}};
 let snapshot=fixture();let limits=SqliteDatabaseLimits::default();let expected=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let rows=expected.tables.iter().map(|table|table.rows.len()).sum::<usize>();assert!(rows>0);
 let bytes=export_sqlite_database(&expected,limits,&mut |_|true).unwrap();
 let script=r#"import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()),{safeIntegers:true});if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const tables=db.query("SELECT name FROM sqlite_schema WHERE type='table' ORDER BY name").all();const rows=tables.reduce((n,t)=>n+Number(db.query('SELECT COUNT(*) AS count FROM "'+t.name.replaceAll('"','""')+'"').get().count),0);await Bun.write(Bun.stdout,String(rows));db.close();"#;
 let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));assert_eq!(String::from_utf8(output.stdout).unwrap().parse::<usize>().unwrap(),rows);
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let payload=snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:rows,..limits})).unwrap();
  let physical=match &payload{store::io::IoPayload::Binary(value)=>value.len(),store::io::IoPayload::Text(value)=>value.len()};assert!(physical>0);
  let repeated=snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:rows,max_file_bytes:physical,..limits})).unwrap();assert_eq!(repeated,payload);
  let restored=En1998Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(restored.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),expected);
  for restricted in[SqliteDatabaseLimits{max_rows:rows-1,..limits},SqliteDatabaseLimits{max_file_bytes:physical-1,..limits},SqliteDatabaseLimits{max_value_bytes:1,..limits}]{assert!(snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,restricted)).is_err(),"{encoding:?}: {restricted:?}");}
  assert!(snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,limits)).is_err());
 }
}
